function get_marriage_divorce_help() {
  const name = prompt("What is your name?");
  const contact = prompt("What is your contact number?");
  const issue = prompt("What issue is the problem?");

  const response = `
  <h1>Help for ${name}</h1>
  <p>Thank you for yours patience.</p>
  <p>Please provide your information so we can assist you with your ${issue}:</p>
  <pre name="contact">${contact}</pre>
  `;
  return response;
}

get_marriage_divorce_help();

